source(file.path(dirname(sub('^--file=','',grep('^--file=',commandArgs(FALSE),value=TRUE)[1])),'full_lung_common.R'))
source(file.path(ROOT,'R','pspline_math.R'))
out<-file.path(ROOT,'results','pspline_lung');dir.create(out,recursive=TRUE,showWarnings=FALSE)
z<-full_load('Weibull-PH');original<-full_read(file.path(z$path,'fit.rds'),z$key);if(is.null(original)||original$status!='complete')stop('Original Weibull fit unavailable or changed');d<-z$d;if(isTRUE(d$frailty)||ncol(d$X)!=3L)stop('Unexpected lung inputs')
if(abs(d$reference_scale-365.25)>1e-8)stop('Reference horizon is not one year')
upper<-ceiling(max(c(1,d$model_time)));spec<-list(version='pspline_ph_v1',upper=upper,knots=upper*c(.25,.5,.75),quadrature=16L,tail='Constant hazard after upper boundary',data_hash=digest::digest(d,algo='sha256'))
K<-ncol(ps_basis(0,spec));D<-diff(diag(K),differences=2);ee<-eigen(crossprod(D),symmetric=TRUE);ix<-which(ee$values>1e-8)
F<-sweep(ee$vectors[,ix,drop=FALSE],2,sqrt(ee$values[ix]),'/');F<-F/exp(mean(log(rowSums(F^2)))/2)
spec$F<-F;spec$trend<-seq(-1,1,length.out=K);spec$K<-K
if(max(abs(colSums(F)))>1e-7||max(abs(crossprod(spec$trend,F)))>1e-7)stop('Spline nullspace not identified')
p<-file.path(out,'spec.rds')
if(file.exists(p)){old<-readRDS(p);if(!identical(digest::digest(old),digest::digest(spec)))stop('P-spline settings changed; old outputs preserved')}else analysis_atomic(spec,p)
source_path<-file.path(ROOT,'models','pspline_ph.stan');code<-paste(readLines(source_path),collapse='\n');h<-digest::digest(code,algo='sha256');target<-file.path(out,'compiled.rds')
if(file.exists(target)){o<-readRDS(target);if(!identical(h,o$source_hash))stop('Stan checkpoint changed');cat('REUSE COMPILED\n');quit(status=0)}
rstan::stanc(model_code=code,model_name='pspline_ph_v1')
co<-rstan::stan_model(model_code=code,model_name='pspline_ph_v1',auto_write=FALSE)
analysis_atomic(list(compiled=co,source_hash=h,aft_prior='matched'),target)
analysis_json(list(model='P-spline-PH',K=K,knots=spec$knots,boundary=upper,reference_days=365.25,quadrature=16,log_tau_prior='Normal(log(.3),.5)',slope_prior='Normal(0,.7)',nullspace='Constant removed; proper Normal prior on linear coefficient',tail=spec$tail),file.path(out,'specification.json'))
cat('PREPARE COMPLETE\n')
